// Package api holds infraweave's API descriptions.
//
// api.openapi.yaml is the API infraweave serves, bundled by
// tools/openapi-bundle from the fragments in src/api. The Spacelift
// references, one per product under reference/spacelift (Deploy) and
// reference/spacelift-flows (Flows), are generated by tools/specref; they
// describe the upstream surface infraweave mirrors, not the API it serves.
// parity-baseline.<product>.json accepts the reference operations
// api.openapi.yaml does not serve unchanged, and parity_test.go fails when a
// baseline accepts too little or too much; make parity-baseline rewrites
// both.
package api

import _ "embed"

// SpaceliftReference is the generated REST projection of the Spacelift API.
//
//go:embed reference/spacelift/spacelift.openapi.yaml
var SpaceliftReference []byte

// FlowsReference is the generated REST projection of the Spacelift Flows
// RPC interface.
//
//go:embed reference/spacelift-flows/flows.openapi.yaml
var FlowsReference []byte

// Served is the bundled API that infraweave serves under /api/v1.
//
//go:embed api.openapi.yaml
var Served []byte
